import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Qvwhmedc.js";var i=JSON.parse(`{"title":"Start In A Fresh Worktree","description":"","frontmatter":{},"headers":[],"relativePath":"skills/contributors/start-in-a-fresh-worktree.md","filePath":"skills/contributors/start-in-a-fresh-worktree.md"}`),a={name:`skills/contributors/start-in-a-fresh-worktree.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="start-in-a-fresh-worktree" tabindex="-1">Start In A Fresh Worktree <a class="header-anchor" href="#start-in-a-fresh-worktree" aria-label="Permalink to “Start In A Fresh Worktree”">​</a></h1><p>Use this skill at the start of every session contributing to WarpDrive itself, before reading code or making any change. Each session gets its own <code>git worktree</code> branched from a freshly fetched <code>origin/main</code> — never the shared primary checkout, and never whatever commit that checkout&#39;s <code>HEAD</code> happens to be parked on.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to “Steps”">​</a></h2><ol><li><p>Don&#39;t work in the primary checkout, even for a &quot;quick&quot; one-file change. <code>pnpm install</code> in this repo also builds every package and rewrites hardlinks into the <code>node_modules</code> of every other package and test app that depends on it (see <a href="/pr-preview/pr-11154/guides/contributing/setting-up-the-project">Setting Up The Project</a>), so two sessions installing or building in the same checkout clobber each other&#39;s build output — and the failures show up later as stale or half-written <code>dist</code> content, not as an obvious conflict.</p></li><li><p>Branch from a freshly fetched <code>origin/main</code>, not from the current <code>HEAD</code>. Any long-lived checkout is usually sitting on an unrelated feature branch; branching off it silently folds someone else&#39;s unmerged commits into your diff and your PR. <code>main</code> is also the branch PRs target, so branching anywhere else guarantees an unnecessary rebase.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> worktree</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">branch-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../warp-drive-</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">topi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin/main</span></span></code></pre></div></li><li><p>Always make the worktree a <strong>sibling</strong> of the repo (<code>../warp-drive-&lt;topic&gt;</code>), never a directory nested inside it. This is not a tidiness preference — Node&#39;s resolution algorithm searches <em>upward</em> for <code>node_modules</code>, so a worktree at <code>&lt;repo&gt;/anything/my-worktree</code> silently resolves any dependency or <code>bin</code> its own install hasn&#39;t provided from <code>&lt;repo&gt;/node_modules</code> — the primary checkout&#39;s tree. Three properties of this repo turn that into a wrong answer rather than an error: <code>pnpm-workspace.yaml</code> sets <code>hoist: false</code> and uses injected workspace packages specifically to keep each test app&#39;s dep tree isolated, <code>pnpm install</code> hardlinks built output into consumers&#39; <code>node_modules</code>, and the packages lean on branded types. So a nested worktree gets the other checkout&#39;s <code>dist</code>, mismatched versions, duplicate modules in a bundle, and private-brand type errors that point nowhere near the cause. A sibling has no shared ancestor holding a <code>node_modules</code>, so resolution can&#39;t cross over.</p><p>Nesting is also the <em>default</em> for Claude Code&#39;s own worktree mechanisms — <code>--worktree</code>, <code>EnterWorktree</code>, and <code>Agent</code> with <code>isolation: &quot;worktree&quot;</code> all create under <code>&lt;repo&gt;/.claude/worktrees/</code> and currently offer no way to relocate that. In this repo, don&#39;t use them: create the sibling yourself with <code>git worktree add</code> as above. <code>.gitignore</code> covers <code>.claude/worktrees/</code> so a nested one that slips in doesn&#39;t pollute <code>git status</code>, but that entry is damage control, not permission.</p></li><li><p>Install from the new worktree&#39;s root. <code>node_modules</code> is not shared between worktrees, so a fresh worktree has no dependencies and no built packages at all until you install:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../warp-drive-</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">topi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>Two setup steps are <em>not</em> per-worktree and don&#39;t need repeating: <code>mise install</code> fetches the pinned <code>node</code>/<code>pnpm</code>/<code>bun</code> toolchain globally, and <code>@warp-drive/holodeck</code>&#39;s <code>ensure-cert</code> writes <code>holodeck-localhost.pem</code> into your home directory. Only run those if you&#39;ve never set the project up on this machine.</p></li><li><p>Run every command from the worktree root for the rest of the session, and don&#39;t <code>cd</code> back into the primary checkout to run tests, lint, or builds — that reintroduces exactly the cross-session build clobbering the worktree exists to prevent.</p></li><li><p>Remember that some git state is shared across all worktrees of a repo, not isolated by one. The stash stack is global: a bare <code>git stash pop</code> can restore another session&#39;s work into your tree, so set work aside with a temporary WIP commit instead, or use <code>git stash push -u -m &quot;&lt;unique-tag&gt;&quot;</code> and <code>git stash apply &lt;sha&gt;</code> against the entry you can identify by tag. Branch checkouts are also global — a branch already checked out in another worktree cannot be checked out in yours.</p></li><li><p>Clean up once the PR merges, so the next session&#39;s <code>git worktree list</code> stays readable:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> worktree</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../warp-drive-</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">topi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> worktree</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prune</span></span></code></pre></div></li></ol><h2 id="why-fresh-and-off-main-are-separate-requirements" tabindex="-1">Why &quot;fresh&quot; and &quot;off main&quot; are separate requirements <a class="header-anchor" href="#why-fresh-and-off-main-are-separate-requirements" aria-label="Permalink to “Why &quot;fresh&quot; and &quot;off main&quot; are separate requirements”">​</a></h2><p>They fail in different ways. Reusing an existing worktree gets you a dirty tree, stale <code>node_modules</code>, and leftover build output from unrelated work — a green local test run there tells you nothing about your change. Branching off the wrong commit gets you a <em>clean</em> worktree whose diff against <code>main</code> contains commits you never wrote; that one survives all local verification and only surfaces in review, as a PR touching files the task never mentioned.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};